// v24.xx (sndA3), HIS ORDER 2026-10-12 (improve the sound, a distinct noise for every action): A HIT ON YOU SAYS WHAT IT HIT. Whether
// your plate took a round or it went into you, you heard the same old square blip (the generic hit every enemy hit and every downed
// hit also plays), so nothing told you your armour was working, or that it had gone. Now the hit on you is heard as what it struck:
//   ALL ON THE PLATE (pplate): a short bright clang, a triangle at 1.1 kHz with its octave and a 3 kHz tick, closer and brighter
//     than the armour hit you hear on a Warden.
//   INTO YOU (pflesh): a dull thump, 150 Hz falling to 55, under a short low smack (the grunt still rides it).
//   BOTH (pmix): the plate tick and the thump together, lighter each.
//   THE PLATE BREAKS (platebreak, once, as your armour reaches 0): a glassy pair at 2.4 and 3.2 kHz falling a fifth over 0.25 s, a
//     high shatter and a low knock, on the HUD bus, the shield break of Fortnite and Apex.
// Live play only (blip already stops under G.sim, and the break is asked for only off the sim). No seeded draw.
function sndAPlayerHit(a,OUT,mat,vol,t){
  var pl=mat!=='pflesh', fl=mat!=='pplate', k=(mat==='pmix')?0.75:1;
  if(pl){
    sndATone(a,OUT,'triangle',1150,1060,0.12,0.085*k*vol,t);
    sndATone(a,OUT,'triangle',2300,2150,0.07,0.03*k*vol,t);
    sndANoise(a,OUT,{dur:0.022,pw:2.5,ft:'highpass',f0:3000,q:0.7,g:0.13*k*vol,at:t});
  }
  if(fl){
    sndATone(a,OUT,'sine',150,55,0.1,0.22*k*vol,t);
    sndANoise(a,OUT,{dur:0.05,pw:2.2,ft:'lowpass',f0:520,q:0.8,g:0.2*k*vol,at:t});
  }
  return true;
}
SND_CAT.platebreak='ui';
SNDA_GEN.platebreak=function(a,OUT,vol,t){
  if(!sndAGate('platebreak',0.2,t)) return;
  sndATone(a,OUT,'triangle',2400,1600,0.25,0.05*vol,t);
  sndATone(a,OUT,'triangle',3200,2133,0.25,0.035*vol,t);
  sndANoise(a,OUT,{dur:0.2,pw:1.6,ft:'highpass',f0:4000,q:0.7,g:0.1*vol,at:t});
  sndATone(a,OUT,'sine',120,70,0.08,0.2*vol,t);
};
